def rm_checkpoints(
    save_dir: str,
    keep_n_latest: int = 0,
):
    """
    Remove old checkpoints.

    Args:
        save_dir (str): The directory to save the checkpoints.
        keep_n_latest (int): The number of latest checkpoints to keep.
    """
    if keep_n_latest <= 0 or dist.get_rank() != 0:
        return
    files = glob(os.path.join(save_dir, "epoch*-global_step*"))
    files = sorted(
        files, key=lambda s: tuple(map(int, re.search(r"epoch(\d+)-global_step(\d+)", s).groups())), reverse=True
    )
    to_remove = files[keep_n_latest:]
    for f in to_remove:
        # shutil.rmtree(f)
        for item in glob(os.path.join(f, "*")):
            if os.path.isdir(item):
                dir_name = os.path.basename(item)
                if dir_name != "eval":
                    shutil.rmtree(item)
            else:
                os.remove(item)

def scan_for_package_data(
    directory: Path,
    package: Path,
    data: t.Optional[t.List[str]] = None,
) -> t.List[str]:
    """Walk the package and scan for package files."""
    data = data or []
    for child in directory.iterdir():
        if child.name.endswith(".py") or child.name.endswith(".pyc"):
            continue

        if child.is_file():
            data.append(str(child.relative_to(package)))
            continue

        data += scan_for_package_data(
            directory=child,
            package=package,
        )
    return data

def add_helicone_headers(source: str) -> str:
    tree = ast.parse(source)
    helicone_adder = HeliconeAdder()
    tree = helicone_adder.visit(tree)
    assert helicone_adder.openai_patched_successfully

    # If the module does not import `os`, then add the import statement
    if not helicone_adder.has_os_import:
        tree.body.insert(0, OS_IMPORT_STMT)

    return ast.unparse(tree)

def __init__(self) -> None:
    self.has_os_import = False
    self.openai_patched_successfully = False

def visit_Import(self, node: ast.Import) -> ast.Import:
    self.generic_visit(node)

    # If the module already imports `os`, then set the flag
    # to indicate that it has been imported.
    for alias in node.names:
        if alias.name == "os":
            self.has_os_import = True

    return node

